CREATE OR REPLACE FUNCTION pg_temp.pp_doc(valor text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT regexp_replace(btrim(coalesce(valor, '')), '\s+', '', 'g')
$$;
CREATE OR REPLACE FUNCTION pg_temp.pp_nombre(valor text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(string_agg(palabra, ' ' ORDER BY palabra), '')
 FROM unnest(regexp_split_to_array(btrim(regexp_replace(
  translate(upper(coalesce(valor, '')), 'ÁÉÍÓÚÜÑ', 'AEIOUUN'), '[^A-Z0-9]+', ' ', 'g')), '\s+')) palabra
 WHERE palabra <> ''
$$;
CREATE OR REPLACE FUNCTION pg_temp.pp_coincidencias(a text, b text) RETURNS int LANGUAGE sql IMMUTABLE AS $$
 SELECT count(*)::int FROM (
  SELECT unnest(string_to_array(pg_temp.pp_nombre(a), ' ')) INTERSECT
  SELECT unnest(string_to_array(pg_temp.pp_nombre(b), ' '))
 ) palabras WHERE unnest <> ''
$$;

DO $$ BEGIN
 IF (SELECT count(*) FROM _pp_padron) <> 330
    OR EXISTS (SELECT dni FROM _pp_padron GROUP BY dni HAVING count(*) > 1)
    OR EXISTS (SELECT 1 FROM _pp_padron WHERE dni !~ '^[0-9]{8,9}$' OR nombre_completo !~ '^[^,]+, [^,]+$')
 THEN RAISE EXCEPTION 'El padrón no pasó la validación: cantidad, documentos o nombres.'; END IF;
END $$;

CREATE TEMP TABLE _pp_actual ON COMMIT DROP AS
SELECT p.*, to_jsonb(p) AS registro, pg_temp.pp_doc(p.dni) AS documento_clave,
 pg_temp.pp_nombre(p.nombre_completo) AS nombre_clave
FROM public.personal p;

-- Dos equivalencias identificadas en la comparación real del 19/10/2026.
-- Solo vinculan la fila fuente a la persona comprobada. NO actualizan su documento.
CREATE TEMP TABLE _pp_equivalencias (
 documento_excel text PRIMARY KEY, persona_id int, documento_actual text, nombre_esperado text
) ON COMMIT DROP;
