CREATE TEMP TABLE _pp_identidades ON COMMIT DROP AS
SELECT r.*, coalesce(exactos.ids, ARRAY[]::int[]) AS ids_exactos,
 CASE WHEN coalesce(cardinality(exactos.ids), 0) = 0
      THEN coalesce(posibles.ids, ARRAY[]::int[]) ELSE ARRAY[]::int[] END AS ids_posibles
FROM _pp_padron r
LEFT JOIN LATERAL (
 SELECT array_agg(p.id ORDER BY p.id) AS ids FROM _pp_actual p
 WHERE p.documento_clave = r.dni OR EXISTS (
  SELECT 1 FROM _pp_equivalencias e
  WHERE e.documento_excel = r.dni AND e.persona_id = p.id
    AND e.documento_actual = p.documento_clave
    AND pg_temp.pp_nombre(e.nombre_esperado) = p.nombre_clave
    AND p.nombre_clave = pg_temp.pp_nombre(r.nombre_completo)
 )
) exactos ON true
LEFT JOIN LATERAL (
 SELECT array_agg(p.id ORDER BY p.id) AS ids FROM _pp_actual p
 WHERE p.nombre_clave = pg_temp.pp_nombre(r.nombre_completo)
    OR (length(regexp_replace(p.documento_clave, '[^0-9]', '', 'g')) >= 6
        AND ltrim(regexp_replace(p.documento_clave, '[^0-9]', '', 'g'), '0') = ltrim(r.dni, '0'))
) posibles ON true;

CREATE TEMP TABLE _pp_plan ON COMMIT DROP AS
WITH catalogo AS (
 SELECT upper(btrim(co.nombre)) AS operacion_clave, count(*) AS opciones,
   min(co.id) AS id, min(co.nombre) AS operacion, min(c.nombre) AS cliente
 FROM public.cliente_operaciones co JOIN public.clientes c ON c.id = co.cliente_id
 WHERE co.activo = true AND c.activo = true GROUP BY upper(btrim(co.nombre))
), origen AS (
 SELECT r.*, p.id AS persona_id, p.registro AS anterior,
 CASE WHEN r.baja_confirmada OR (r.fecha_cese IS NOT NULL AND r.fecha_cese <= f.fecha_negocio)
      THEN 'Inactivo' ELSE 'Activo' END AS estado_propuesto,
 CASE WHEN coalesce(c.opciones, 0) = 1 THEN c.id ELSE NULL END AS nueva_relacion,
 CASE WHEN coalesce(c.opciones, 0) = 1 THEN c.cliente ELSE NULL END AS nuevo_cliente,
 CASE WHEN coalesce(c.opciones, 0) = 1 THEN c.operacion ELSE NULL END AS nueva_operacion
 FROM _pp_identidades r CROSS JOIN _pp_config f
 LEFT JOIN _pp_actual p ON p.id = r.ids_exactos[1]
 LEFT JOIN catalogo c ON c.operacion_clave = upper(btrim(r.area))
), propuesto AS (
 SELECT o.*,
 jsonb_build_object('nombre_completo', o.nombre_completo, 'modalidad', o.modalidad,
 'area', o.area, 'cargo', o.cargo, 'estado', o.estado_propuesto)
 || CASE WHEN o.persona_id IS NULL THEN jsonb_build_object('dni', o.dni,
    'cliente_operacion_id', o.nueva_relacion, 'cliente', o.nuevo_cliente, 'operacion', o.nueva_operacion)
    ELSE '{}'::jsonb END AS cambios
 FROM origen o
)
SELECT r.fila_excel, r.dni, r.nombre_completo, r.persona_id, r.anterior, r.cambios,
 (SELECT to_jsonb(p) FROM _pp_padron p WHERE p.dni = r.dni) AS datos_fuente,
 r.ids_exactos, r.ids_posibles,
 CASE WHEN cardinality(r.ids_exactos) > 1 THEN 'REVISAR_DOCUMENTO_DUPLICADO'
      WHEN cardinality(r.ids_exactos) = 0 AND cardinality(r.ids_posibles) > 0 THEN 'REVISAR_IDENTIDAD'
      WHEN r.persona_id IS NOT NULL AND coalesce(r.anterior->>'nombre_completo', '') <> ''
       AND pg_temp.pp_coincidencias(r.nombre_completo, r.anterior->>'nombre_completo') < 2 THEN 'REVISAR_NOMBRE'
      WHEN r.persona_id IS NULL THEN 'ALTA'
      WHEN lower(btrim(coalesce(r.anterior->>'estado', ''))) = 'inactivo' AND r.estado_propuesto = 'Activo' THEN 'REACTIVAR'
      WHEN lower(btrim(coalesce(r.anterior->>'estado', ''))) <> 'inactivo' AND r.estado_propuesto = 'Inactivo' THEN 'DESACTIVAR_CESE'
      WHEN r.anterior || r.cambios IS DISTINCT FROM r.anterior THEN 'ACTUALIZAR'
      ELSE 'SIN_CAMBIOS' END AS accion,
 (r.persona_id IS NULL AND r.nueva_relacion IS NULL) AS requiere_asignacion
FROM propuesto r;

INSERT INTO _pp_plan (fila_excel, dni, nombre_completo, persona_id, anterior, cambios,
 datos_fuente, ids_exactos, ids_posibles, accion, requiere_asignacion)
SELECT NULL, p.dni, p.nombre_completo, p.id, p.registro, jsonb_build_object('estado', 'Inactivo'),
 NULL, ARRAY[p.id], ARRAY[]::int[], 'DESACTIVAR_AUSENTE', false
FROM _pp_actual p
WHERE NOT EXISTS (SELECT 1 FROM _pp_identidades r WHERE p.id = ANY(r.ids_exactos))
 AND lower(btrim(coalesce(p.estado, ''))) <> 'inactivo'
 AND NOT EXISTS (SELECT 1 FROM _pp_plan r WHERE r.accion LIKE 'REVISAR_%' AND p.id = ANY(r.ids_posibles));

-- Resumen de acciones contra la base a la que está conectada esta terminal.
SELECT accion, count(*)::int AS personas FROM _pp_plan GROUP BY accion ORDER BY accion;
-- Diferencias de formato ya vinculadas: se conservan documento e ID actuales.
SELECT e.persona_id, e.nombre_esperado AS nombre_completo,
 e.documento_excel, e.documento_actual,
 'Se conserva el documento del ERP y no se crea otra persona' AS tratamiento
FROM _pp_equivalencias e JOIN _pp_identidades r ON r.dni = e.documento_excel
 WHERE e.persona_id = ANY(r.ids_exactos) ORDER BY e.persona_id;
-- Identidades que requieren revisar: no se cambian documentos ni se crean duplicados.
SELECT r.fila_excel, r.dni AS documento_excel, r.nombre_completo AS nombre_excel,
 r.accion, p.id AS persona_id, p.dni AS documento_actual, p.nombre_completo AS nombre_actual
FROM _pp_plan r LEFT JOIN _pp_actual p ON p.id = ANY(r.ids_exactos || r.ids_posibles)
WHERE r.accion LIKE 'REVISAR_%' ORDER BY r.fila_excel, p.id;
-- Altas nuevas y sus asignaciones, cuando el catálogo permite una sola coincidencia.
SELECT fila_excel, dni, nombre_completo, cambios->>'estado' AS estado,
 cambios->>'area' AS area, cambios->>'cargo' AS cargo,
 cambios->>'cliente' AS cliente, cambios->>'operacion' AS operacion,
 requiere_asignacion AS asignacion_pendiente
FROM _pp_plan WHERE accion = 'ALTA' ORDER BY fila_excel;
-- Bajas que se realizarían. No se eliminan personas ni sus relaciones históricas.
SELECT persona_id, dni, nombre_completo, accion,
 anterior->>'estado' AS estado_actual, cambios->>'estado' AS estado_nuevo
FROM _pp_plan WHERE accion IN ('DESACTIVAR_CESE', 'DESACTIVAR_AUSENTE') ORDER BY nombre_completo;
-- Cambios y reactivaciones que ya tienen un documento coincidente.
SELECT persona_id, dni, nombre_completo, accion,
 anterior->>'cargo' AS cargo_actual, cambios->>'cargo' AS cargo_nuevo,
 anterior->>'area' AS area_actual, cambios->>'area' AS area_nueva
FROM _pp_plan WHERE accion IN ('ACTUALIZAR', 'REACTIVAR') ORDER BY nombre_completo;
-- Ceses futuros: no se adelantan ni se programan tareas automáticas.
SELECT r.dni, r.nombre_completo, r.fecha_cese,
 'Permanece Activo; ejecutar su baja cuando corresponda' AS tratamiento
FROM _pp_padron r CROSS JOIN _pp_config f WHERE r.fecha_cese > f.fecha_negocio;
-- Las cuentas de acceso no se desactivan como efecto oculto de actualizar personal.
SELECT u.id AS usuario_id, u.username, u.rol, r.persona_id, r.nombre_completo,
 'Revisar acceso: el personal quedará inactivo' AS observacion
FROM public.usuarios u JOIN _pp_plan r ON r.persona_id = u.persona_id
WHERE r.accion IN ('DESACTIVAR_CESE', 'DESACTIVAR_AUSENTE')
 AND lower(btrim(coalesce(u.estado, ''))) = 'activo' ORDER BY u.id;

